async function loadLocale(code){
  lang=code;
  translations=embeddedLocales[code]||embeddedLocales.ar;
  document.documentElement.lang=code;
  document.documentElement.dir=code==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(translations[k])el.textContent=translations[k]});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const k=el.dataset.i18nPlaceholder;if(translations[k])el.placeholder=translations[k]});
  const m=pageMeta[currentPage]||pageMeta.overview;
  $('pageTitle').textContent=t(m[0]);
  $('pageDesc').textContent=t(m[1]);
  renderAll();
}
function t(k){return translations[k]||k} function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function numeric(v){if(typeof v==='number'&&Number.isFinite(v))return v;if(typeof v==='string'&&v.trim()!==''&& /^[-+]?\d+(?:[.,]\d+)?%?$/.test(v.trim())){let n=Number(v.trim().replace('%','').replace(',','.'));return v.trim().endsWith('%')?n/100:n;}return null}
function isNumericColumn(h){const vals=allRecords.slice(0,500).map(r=>r[h]).filter(v=>v!==null&&v!==''&&v!==undefined);return vals.length>0&&vals.filter(v=>numeric(v)!==null).length/vals.length>=.75}
function numericColumns(){return headers.filter(isNumericColumn)}
function missingTotal(rows=allRecords){return rows.reduce((n,r)=>n+headers.filter(h=>r[h]===null||r[h]===undefined||r[h]==='').length,0)}
function rowKey(r){return JSON.stringify(headers.map(h=>r[h]??null))}function duplicateCount(rows=allRecords){const s=new Set();let n=0;rows.forEach(r=>{const k=rowKey(r);if(s.has(k))n++;else s.add(k)});return n}
function setOptions(id,items,selected){const el=$(id);if(!el)return;const old=selected||el.value;el.innerHTML='';items.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;el.appendChild(o)});if(items.includes(old))el.value=old;}
function setupSelects(){setOptions('filterColumn',headers);setOptions('categoryColumn',headers.find(h=>!isNumericColumn(h))?[...headers.filter(h=>!isNumericColumn(h)),...numericColumns()]:headers);setOptions('statsColumn',headers);setOptions('pivotGroup',headers);setOptions('pivotValue',['(count)',...numericColumns()]);setOptions('dashCategory',headers);setOptions('dashValue',['(count)',...numericColumns()]);}
async function importFiles(){toast(t('demoImportDisabled')||'Demo uses the preloaded sample dataset.');}
function applyFilters(){const col=$('filterColumn').value,val=$('filterValue').value.trim().toLocaleLowerCase();filteredRecords=allRecords.filter(r=>!val||String(r[col]??'').toLocaleLowerCase().includes(val));page=1;$('filterStatus').textContent=`${filteredRecords.length} / ${allRecords.length}`;renderAll()}
function clearFilters(){ $('filterValue').value='';filteredRecords=[...allRecords];$('filterStatus').textContent='';page=1;renderAll() }
function visibleRecords(){const q=$('searchRows')?.value?.toLocaleLowerCase()||'';return filteredRecords.filter(r=>!q||headers.some(h=>String(r[h]??'').toLocaleLowerCase().includes(q)))}
function renderAll(){if(!allRecords.length)return;const rows=filteredRecords;$('rowCount').textContent=rows.length.toLocaleString();$('colCount').textContent=headers.length.toLocaleString();$('missingCount').textContent=missingTotal(rows).toLocaleString();$('duplicateCount').textContent=duplicateCount(rows).toLocaleString();renderInsights();renderTable();renderCharts();renderStats();if(currentPage==='dashboard')buildDashChart(false);}
function renderInsights(){const numericCols=numericColumns();const insights=[];insights.push([t('filterRows'),filteredRecords.length.toLocaleString(),`${t('of')} ${allRecords.length.toLocaleString()} ${t('rowsLabel')}`]);insights.push([t('unique'),headers.length?Math.max(...headers.map(h=>new Set(filteredRecords.map(r=>String(r[h]??'∅'))).size)):0,t('columns')]);if(numericCols.length){const h=numericCols[0],v=filteredRecords.map(r=>numeric(r[h])).filter(n=>n!==null);insights.push([`${t('mean')} · ${h}`,fmt(avg(v)),`${t('min')}: ${fmt(Math.min(...v))} · ${t('max')}: ${fmt(Math.max(...v))}`]);}else insights.push([t('missing'),missingTotal(filteredRecords),t('missingNote')]);$('insights').innerHTML=insights.map(([a,b,c])=>`<div class="insight"><span>${escapeHtml(String(a))}</span><strong>${escapeHtml(String(b))}</strong><p>${escapeHtml(String(c))}</p></div>`).join('')}
function fmt(v){return v===null||v===undefined||!Number.isFinite(v)?'—':new Intl.NumberFormat(lang==='ar'?'ar-MA':lang==='fr'?'fr-FR':'en-US',{maximumFractionDigits:3}).format(v)}function avg(a){return a.length?a.reduce((s,v)=>s+v,0)/a.length:null}function median(a){if(!a.length)return null;const b=[...a].sort((x,y)=>x-y),m=Math.floor(b.length/2);return b.length%2?b[m]:(b[m-1]+b[m])/2}function mode(a){if(!a.length)return '—';const c=new Map();a.forEach(v=>c.set(v,(c.get(v)||0)+1));return [...c.entries()].sort((x,y)=>y[1]-x[1])[0][0]}
function renderTable(){const rows=visibleRecords(),maxPage=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,maxPage);const slice=rows.slice((page-1)*pageSize,page*pageSize);$('dataTable').querySelector('thead').innerHTML='<tr>'+headers.map(h=>`<th>${escapeHtml(h)}</th>`).join('')+'</tr>';$('dataTable').querySelector('tbody').innerHTML=slice.map(r=>'<tr>'+headers.map(h=>`<td title="${escapeHtml(String(r[h]??''))}">${escapeHtml(displayValue(r[h]))}</td>`).join('')+'</tr>').join('');$('tableCount').textContent=`${rows.length.toLocaleString()} ${t('rowsLabel')}`;$('pageInfo').textContent=`${t('page')} ${page} ${t('of')} ${maxPage}`;$('prevPage').disabled=page<=1;$('nextPage').disabled=page>=maxPage;}
function displayValue(v){if(v===null||v===undefined)return '—';if(typeof v==='object')return JSON.stringify(v);return String(v)}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function destroyChart(id){if(charts[id]){charts[id].destroy();delete charts[id]}}function palette(){return ['#217346','#62a779','#8abf9a','#b1d5ba','#4d87a5','#d4a64d','#8060b7','#d47763','#5f7770','#9eb8ce']}
function chartOptions(){return {responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:true}},scales:{x:{grid:{display:false},ticks:{maxRotation:30,autoSkip:true}},y:{beginAtZero:true,grid:{color:'#edf1ed'}}}}}
function renderCharts(){const cat=$('categoryColumn')?.value;if(!cat)return;const counts=new Map();filteredRecords.forEach(r=>{const k=String(r[cat]??'(blank)');counts.set(k,(counts.get(k)||0)+1)});const pairs=[...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,12);destroyChart('bar');charts.bar=new Chart($('barChart'),{type:'bar',data:{labels:pairs.map(x=>x[0]),datasets:[{data:pairs.map(x=>x[1]),backgroundColor:palette(),borderRadius:5}]},options:chartOptions()});const nums=numericColumns().slice(0,8);destroyChart('num');if(nums.length){charts.num=new Chart($('numChart'),{type:'bar',data:{labels:nums,datasets:[{label:t('mean'),data:nums.map(h=>avg(filteredRecords.map(r=>numeric(r[h])).filter(v=>v!==null))),backgroundColor:'#217346',borderRadius:5}]},options:chartOptions()});}else{const ctx=$('numChart').getContext('2d');ctx.clearRect(0,0,$('numChart').width,$('numChart').height);ctx.font='14px Segoe UI';ctx.fillStyle='#75817a';ctx.fillText(t('noNumeric'),20,45)}}
function renderStats(){const col=$('statsColumn')?.value;if(!col)return;const vals=filteredRecords.map(r=>numeric(r[col])).filter(v=>v!==null),strs=filteredRecords.map(r=>r[col]).filter(v=>v!==null&&v!=='');const num=isNumericColumn(col);let data=[[t('column'),col],[t('count'),strs.length],[t('unique'),new Set(strs.map(String)).size],[t('missing'),filteredRecords.length-strs.length]];if(num){data.push([t('mean'),fmt(avg(vals))],[t('median'),fmt(median(vals))],[t('mode'),fmt(mode(vals))],[t('min'),fmt(vals.length?Math.min(...vals):null)],[t('max'),fmt(vals.length?Math.max(...vals):null)],[t('total'),fmt(vals.reduce((a,b)=>a+b,0))]);} $('statsTable').querySelector('thead').innerHTML=`<tr><th>${t('column')}</th><th>${t('value')}</th></tr>`;$('statsTable').querySelector('tbody').innerHTML=data.map(([a,b])=>`<tr><td>${escapeHtml(String(a))}</td><td>${escapeHtml(String(b))}</td></tr>`).join('');const findings=[];findings.push(`${t('rows')}: ${filteredRecords.length.toLocaleString()} · ${t('columns')}: ${headers.length} · ${t('missing')}: ${missingTotal(filteredRecords)}`);if(duplicateCount(filteredRecords))findings.push(`${t('duplicates')}: ${duplicateCount(filteredRecords)}. ${t('removeDuplicatesDesc')}`);if(num&&vals.length){const mean=avg(vals),sd=Math.sqrt(avg(vals.map(v=>(v-mean)**2))||0);const out=sd?vals.filter(v=>Math.abs(v-mean)>3*sd).length:0;if(out)findings.push(`${out} ${t('other')} (${col}) ${t('outliers')||'values are more than three standard deviations from the mean; review before excluding.'}`);findings.push(`${col}: ${t('mean')} ${fmt(mean)}, ${t('median')} ${fmt(median(vals))}.`)}$('autoFindings').innerHTML=findings.map(f=>`<div class="finding">${escapeHtml(f)}</div>`).join('')}
function navigate(pageName){currentPage=pageName;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===pageName));const m=pageMeta[pageName]||pageMeta.overview;$('pageTitle').textContent=t(m[0]);$('pageDesc').textContent=t(m[1]);const panels={overview:['overviewPanel','chartsArea','dataPanel'],data:['dataPanel'],clean:['cleanPanel'],analysis:['analysisPanel'],pivot:['pivotPanel'],dashboard:['dashboardPanel'],reports:['reportsPanel']};['overviewPanel','chartsArea','dataPanel','cleanPanel','analysisPanel','pivotPanel','dashboardPanel','reportsPanel'].forEach(id=>$(id).classList.add('hidden'));(panels[pageName]||[]).forEach(id=>$(id).classList.remove('hidden'));if(pageName==='dashboard')buildDashChart(false);if(pageName==='pivot'&&pivotRows.length)showPivot(pivotRows);}
function saveUndo(){undoSnapshot={headers:[...headers],records:allRecords.map(r=>({...r}))}}
function cleanOperation(kind){if(!allRecords.length){toast(t('noData'));return;}saveUndo();let changed=0;if(kind==='trim'){allRecords=allRecords.map(r=>{const n={...r};headers.forEach(h=>{if(typeof n[h]==='string'){const v=n[h].trim().replace(/\s+/g,' ');if(v!==n[h])changed++;n[h]=v;}});return n;});cleanReport=`${t('trim')}: ${changed}`;}else if(kind==='duplicates'){const seen=new Set();const next=[];allRecords.forEach(r=>{const k=rowKey(r);if(seen.has(k))changed++;else{seen.add(k);next.push(r)}});if(!changed){undoSnapshot=null;toast(t('noDuplicates'));return;}allRecords=next;cleanReport=`${t('removeDuplicates')}: ${changed}`;}else if(kind==='empty'){const next=allRecords.filter(r=>headers.some(h=>r[h]!==null&&r[h]!==''&&r[h]!==undefined));changed=allRecords.length-next.length;if(!changed){undoSnapshot=null;toast(t('noEmptyRows'));return;}allRecords=next;cleanReport=`${t('dropEmpty')}: ${changed}`;}else if(kind==='rename'){const old=prompt(t('renameColumn')+':\n'+headers.join('\n'),headers[0]);if(!old||!headers.includes(old)){undoSnapshot=null;return;}const nn=prompt(t('renameColumn')+' — '+old,old);if(!nn||headers.includes(nn)){undoSnapshot=null;toast('');return;}headers=headers.map(h=>h===old?nn:h);allRecords=allRecords.map(r=>{const n={...r};n[nn]=n[old];delete n[old];return n});changed=1;cleanReport=`${old} → ${nn}`;}
filteredRecords=[...allRecords];setupSelects();renderAll();$('cleanLog').textContent=`${t('cleanDone')} ${cleanReport}`;$('undoClean').disabled=!undoSnapshot;toast(`${t('success')}: ${changed}`)}
function undoClean(){if(!undoSnapshot)return;headers=undoSnapshot.headers;allRecords=undoSnapshot.records;filteredRecords=[...allRecords];undoSnapshot=null;$('undoClean').disabled=true;setupSelects();renderAll();$('cleanLog').textContent=t('cleanHint');toast(t('success'))}
function runPivot(){const group=$('pivotGroup').value,val=$('pivotValue').value,op=$('pivotAgg').value,groups=new Map();filteredRecords.forEach(r=>{const k=String(r[group]??'(blank)');if(!groups.has(k))groups.set(k,[]);if(val==='(count)')groups.get(k).push(1);else{const n=numeric(r[val]);if(n!==null)groups.get(k).push(n)}});pivotRows=[...groups.entries()].map(([key,a])=>({[group]:key,[`${op}(${val})`]:op==='count'?a.length:op==='sum'?a.reduce((s,v)=>s+v,0):op==='avg'?avg(a):op==='min'?(a.length?Math.min(...a):null):a.length?Math.max(...a):null})).sort((a,b)=>(numeric(b[Object.keys(b)[1]])??0)-(numeric(a[Object.keys(a)[1]])??0));showPivot(pivotRows)}function showPivot(rows){const hs=rows.length?Object.keys(rows[0]):[];$('pivotTable').querySelector('thead').innerHTML='<tr>'+hs.map(h=>`<th>${escapeHtml(h)}</th>`).join('')+'</tr>';$('pivotTable').querySelector('tbody').innerHTML=rows.map(r=>'<tr>'+hs.map(h=>`<td>${escapeHtml(String(r[h]??''))}</td>`).join('')+'</tr>').join('')}
function buildDashChart(showToast=true){if(!allRecords.length)return;const type=$('dashType').value,cat=$('dashCategory').value,val=$('dashValue').value,title=$('dashTitle').value||'Data visualization';let dataLabels=[],dataValues=[];if(type==='scatter'){const nums=numericColumns();if(nums.length<2){toast(t('noNumeric'));return;}const pts=filteredRecords.map(r=>({x:numeric(r[nums[0]]),y:numeric(r[nums[1]])})).filter(p=>p.x!==null&&p.y!==null).slice(0,5000);destroyChart('dash');charts.dash=new Chart($('dashChart'),{type:'scatter',data:{datasets:[{label:title,data:pts,backgroundColor:'#217346'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{title:{display:true,text:title}},scales:{x:{title:{display:true,text:nums[0]}},y:{title:{display:true,text:nums[1]}}}}});if(showToast)toast(t('success'));return;}
 const groups=new Map();filteredRecords.forEach(r=>{const k=String(r[cat]??'(blank)');if(!groups.has(k))groups.set(k,[]);const n=val==='(count)'?1:numeric(r[val]);if(n!==null)groups.get(k).push(n)});const pairs=[...groups.entries()].map(([k,a])=>[k,val==='(count)'?a.length:a.reduce((s,v)=>s+v,0)]).sort((a,b)=>b[1]-a[1]).slice(0,30);dataLabels=pairs.map(p=>p[0]);dataValues=pairs.map(p=>p[1]);destroyChart('dash');charts.dash=new Chart($('dashChart'),{type:type==='pie'?'pie':type,data:{labels:dataLabels,datasets:[{label:title,data:dataValues,backgroundColor:palette(),borderRadius:type==='pie'?0:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{title:{display:true,text:title},legend:{display:type==='pie',position:'bottom'}},scales:type==='pie'?{}:chartOptions().scales}});if(showToast)toast(t('success'))}
function saveDashboard(){const config={type:$('dashType').value,cat:$('dashCategory').value,val:$('dashValue').value,title:$('dashTitle').value};localStorage.setItem('excelIntelligence.dashboard',JSON.stringify(config));toast(t('success'))}function loadDashboard(){try{const c=JSON.parse(localStorage.getItem('excelIntelligence.dashboard')||'null');if(c){$('dashType').value=c.type||'bar';$('dashCategory').value=c.cat||headers[0];$('dashValue').value=c.val||'(count)';$('dashTitle').value=c.title||'Data visualization';}}catch(e){}}
function downloadBlob(content,type,filename){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportExcel(rows=filteredRecords,hs=headers,filename='analysis.xlsx'){if(!rows.length){toast(t('noData'));return;}if(!window.XLSX){toast('Excel export library is unavailable');return;}const ws=XLSX.utils.json_to_sheet(rows,{header:hs});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Analysis');XLSX.writeFile(wb,filename);toast(t('exportDone'));}
async function exportCSV(rows=filteredRecords,hs=headers,filename='analysis.csv'){if(!rows.length){toast(t('noData'));return;}const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\ufeff'+[hs.map(esc).join(','),...rows.map(r=>hs.map(h=>esc(r[h])).join(','))].join('\r\n');downloadBlob(csv,'text/csv;charset=utf-8',filename);toast(t('exportDone'));}
function reportHTML(quality=false){const now=new Date().toLocaleString(lang==='ar'?'ar-MA':lang==='fr'?'fr-FR':'en-US');const summary=quality?[[t('rows'),filteredRecords.length],[t('columns'),headers.length],[t('emptyCells'),missingTotal(filteredRecords)],[t('duplicateRows'),duplicateCount(filteredRecords)]]:[[t('rows'),filteredRecords.length],[t('columns'),headers.length],[t('emptyCells'),missingTotal(filteredRecords)],[t('duplicateRows'),duplicateCount(filteredRecords)]];let stats='';const nums=numericColumns();if(!quality&&nums.length)stats='<h2>'+t('numericStats')+'</h2><table><tr><th>'+t('column')+'</th><th>'+t('count')+'</th><th>'+t('mean')+'</th><th>'+t('median')+'</th><th>'+t('min')+'</th><th>'+t('max')+'</th><th>'+t('total')+'</th></tr>'+nums.map(h=>{const a=filteredRecords.map(r=>numeric(r[h])).filter(v=>v!==null);return `<tr><td>${escapeHtml(h)}</td><td>${a.length}</td><td>${fmt(avg(a))}</td><td>${fmt(median(a))}</td><td>${fmt(a.length?Math.min(...a):null)}</td><td>${fmt(a.length?Math.max(...a):null)}</td><td>${fmt(a.reduce((s,v)=>s+v,0))}</td></tr>`}).join('')+'</table>';
return `<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><style>body{font-family:Arial,"Segoe UI",sans-serif;color:#24352a;padding:28px}h1{color:#217346;border-bottom:2px solid #217346;padding-bottom:12px}h2{margin-top:28px;color:#217346;font-size:17px}p{color:#64736a}table{border-collapse:collapse;width:100%;margin-top:15px;font-size:11px}th,td{border:1px solid #dbe5dd;padding:8px;text-align:start}th{background:#eaf4ed} .summary{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.item{padding:10px;border:1px solid #dbe5dd}</style><h1>${t('report')} — ${escapeHtml(currentFile||'')}</h1><p>${t('generated')}: ${now}</p><h2>${quality?t('quality'):t('quickInsights')}</h2><div class="summary">${summary.map(([a,b])=>`<div class="item"><b>${a}</b>: ${b}</div>`).join('')}</div>${stats}<h2>${t('preview')}</h2><table><tr>${headers.slice(0,12).map(h=>`<th>${escapeHtml(h)}</th>`).join('')}</tr>${filteredRecords.slice(0,100).map(r=>'<tr>'+headers.slice(0,12).map(h=>`<td>${escapeHtml(displayValue(r[h]))}</td>`).join('')+'</tr>').join('')}</table><p>${t('rows')}: ${filteredRecords.length}. ${t('exportNote')}</p></html>`}
async function exportPDF(quality=false){if(!allRecords.length){toast(t('noData'));return;}const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print the report');return;}w.document.write(reportHTML(quality));w.document.close();w.focus();setTimeout(()=>w.print(),400)}
function exportPivot(){if(!pivotRows.length){toast(t('noData'));return;}exportExcel(pivotRows,Object.keys(pivotRows[0]),'analysis-table.xlsx')}
function init(){ $('language').addEventListener('change',e=>loadLocale(e.target.value));$('importBtn').addEventListener('click',importFiles);$('welcomeImport').addEventListener('click',importFiles);$('applyFilter').addEventListener('click',applyFilters);$('clearFilters').addEventListener('click',clearFilters);$('filterValue').addEventListener('keydown',e=>{if(e.key==='Enter')applyFilters()});$('categoryColumn').addEventListener('change',renderCharts);$('statsColumn').addEventListener('change',renderStats);$('searchRows').addEventListener('input',()=>{page=1;renderTable()});$('prevPage').addEventListener('click',()=>{page--;renderTable()});$('nextPage').addEventListener('click',()=>{page++;renderTable()});document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.goto)));$('trimText').addEventListener('click',()=>cleanOperation('trim'));$('removeDuplicates').addEventListener('click',()=>cleanOperation('duplicates'));$('renameColumn').addEventListener('click',()=>cleanOperation('rename'));$('dropEmptyRows').addEventListener('click',()=>cleanOperation('empty'));$('undoClean').addEventListener('click',undoClean);$('runPivot').addEventListener('click',runPivot);$('exportPivot').addEventListener('click',exportPivot);$('buildDashboard').addEventListener('click',()=>buildDashChart());$('saveDashboard').addEventListener('click',saveDashboard);$('exportExcelQuick').addEventListener('click',()=>exportExcel());$('reportExcel').addEventListener('click',()=>exportExcel());$('reportCSV').addEventListener('click',()=>exportCSV());$('reportPDF').addEventListener('click',()=>exportPDF(false));$('qualityReport').addEventListener('click',()=>exportPDF(true));}

