function loadDemoData(){
  headers=[...workbookDemoData.headers];
  allRecords=workbookDemoData.rows.map(row=>({...row}));
  filteredRecords=[...allRecords];
  currentFile='sales-orders.xlsx';
  $('welcome')?.classList.add('hidden');
  $('workArea').classList.remove('hidden');
  $('fileBadge').classList.add('loaded');
  $('fileBadge').textContent='● '+(t('demoDataset')||'Demo sales dataset');
  setupSelects();
  renderAll();
  navigate('overview');
}

async function startDemo(){
  init();
  const requestedLanguage = new URLSearchParams(window.location.search).get('lang');
  const savedLanguage = (()=>{try{return localStorage.getItem('ei-language')}catch(e){return null}})();
  const initialLanguage = ['ar','fr','en'].includes(requestedLanguage) ? requestedLanguage :
    (['ar','fr','en'].includes(savedLanguage) ? savedLanguage : 'ar');
  $('language').value = initialLanguage;
  await loadLocale(initialLanguage);
  loadDemoData();
}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',startDemo,{once:true});}else{startDemo();}
